function pictogram(name){const p={home:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>',waves:'<path d="M2 7q5-5 10 0t10 0M2 13q5-5 10 0t10 0M2 19q5-5 10 0t10 0"/>',clipboard:'<rect x="5" y="4" width="15" height="18" rx="2"/><path d="M9 3h7v4H9zM9 12h7m-7 5h7"/>',gear:'<path d="m9 3 1-2h4l1 3 3 1 3-1 2 4-2 2v4l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-4L1 8l2-4 3 1z"/><circle cx="12" cy="12" r="4"/>',alert:'<path d="m12 2 11 19H1Z"/><path d="M12 8v6m0 3v1"/>',check:'<path d="m3 12 6 6L21 5"/>',clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 3"/>',robot:'<rect x="3" y="6" width="18" height="15" rx="5"/><path d="M12 2v4M1 12v4m22-4v4M8 16q4 3 8 0"/><circle cx="8" cy="11" r="1"/><circle cx="16" cy="11" r="1"/>',battery:'<rect x="2" y="6" width="18" height="13" rx="2"/><path d="M22 10v5M6 9v7m4-7v7m4-7v7"/>',sun:'<circle cx="12" cy="10" r="4"/><path d="M12 1v2M3 10H1m22 0h-2M5 3l2 2m12-2-2 2M3 19h18l-2-5H5Zm5-5-1 5m9-5 1 5M12 19v4"/>',calendar:'<rect x="3" y="5" width="18" height="17" rx="2"/><path d="M7 2v6m10-6v6M3 11h18M7 15h2m4 0h3m-9 4h2"/>',buoy:'<path d="M12 2v4m-7 7h14m-7-7a7 7 0 0 1 0 14 7 7 0 0 1 0-14ZM2 22q5-4 10 0t10 0"/>'};return '<svg class="pictogram '+name+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true">'+(p[name]||p.check)+'</svg>'}
function adjustmentGraphic(){const rope=(x,y)=>`<path d="M${x} 47v${y-47}" stroke="#526d82" stroke-width="3"/><ellipse cx="${x}" cy="${y}" rx="10" ry="15" fill="url(#shell)" stroke="#305777" stroke-width="2"/>`;return `<div class="adjust-figure"><svg viewBox="0 0 320 160" role="img" aria-label="수하연 하단을 줄이는 전후 비교. 현재 굴 분포 2~5m, 추천 후보 2~4m"><defs><pattern id="shell" width="6" height="6" patternUnits="userSpaceOnUse"><rect width="6" height="6" fill="#f3e6c6"/><path d="m0 0 6 6m-6 0L6 0" stroke="#a8a28b" stroke-width="1"/></pattern></defs><path d="M10 30q12-8 24 0t24 0t24 0t24 0t24 0M190 30q12-8 24 0t24 0t24 0t24 0t24 0" stroke="#2c9cc1" stroke-width="3" fill="none"/><path d="M22 47h110m60 0h110" stroke="#234e75" stroke-width="5"/>${[40,77,114].map(x=>rope(x,112)).join('')}${[210,247,284].map(x=>rope(x,84)).join('')}<path d="M145 79h30m-10-9 10 9-10 9" fill="none" stroke="#2f9b65" stroke-width="6"/><text x="77" y="150" text-anchor="middle" fill="#234e75" font-size="14" font-weight="700">현재 2~5m</text><text x="247" y="150" text-anchor="middle" fill="#234e75" font-size="14" font-weight="700">추천 후보 2~4m</text></svg></div>`}
